import{_ as d,o,c,a3 as t}from"./chunks/framework.DAK02U1-.js";const h=JSON.parse('{"title":"PGO","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"PGO | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/zh/xclang/design/pgo"}],["meta",{"property":"og:image","content":"https://docs.clice.io/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"zh_CN"}],["link",{"rel":"canonical","href":"https://docs.clice.io/zh/xclang/design/pgo"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/xclang/design/pgo"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/xclang/design/pgo"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://docs.clice.io/zh/xclang/design/pgo"}]]},"headers":[],"relativePath":"zh/xclang/design/pgo.md","filePath":"zh/xclang/design/pgo.md","lastUpdated":1794509097000}'),n={name:"zh/xclang/design/pgo.md"};function a(l,e,r,i,s,g){return o(),c("div",null,[...e[0]||(e[0]=[t('<h1 id="pgo" tabindex="-1">PGO <a class="header-anchor" href="#pgo" aria-label="Permalink to &quot;PGO&quot;">​</a></h1><p>在全部六个主机平台上，xclang 的 <code>clang</code> 与 <code>lld</code> 均使用在 Linux x64 上采集的单份前端 profile 开启按 profile 引导的优化（PGO）与 ThinLTO 构建。在 23.1.2.6 的 C++ 基准测试中，xclang 在 Linux 与 macOS 上的编译速度与 LLVM 官方的 PGO+ThinLTO 发布构建持平，在 Windows x64 上则比 LLVM 官方构建快 11% 至 22%；在 23.1.2.1 中，相比未启用 PGO 的同一构建，这份 profile 将 C++ 编译耗时缩短了 16% 至 34%。</p><h2 id="训练负载" tabindex="-1">训练负载 <a class="header-anchor" href="#训练负载" aria-label="Permalink to &quot;训练负载&quot;">​</a></h2><p>PGO 会针对训练期间实际执行的代码路径优化编译器与链接器。在 <a href="https://github.com/clice-io/xclang/blob/main/toolchain/pgo/train.ts" target="_blank" rel="noreferrer"><code>toolchain/pgo/train.ts</code></a> 中，带插桩的 Linux x64 版 <code>clang</code>、<code>clang-scan-deps</code> 与 <code>lld</code> 会运行同时覆盖构建系统与语言服务器场景的训练负载：</p><ul><li><strong>C 与 C++ 编译</strong>：在 <code>-O0 -g</code> 与 <code>-O2</code> 下为 <code>x86_64</code> 和 <code>aarch64</code> Linux 编译 Abseil（<code>-std=c++20</code>）与 SQLite（<code>sqlite3.c</code>、<code>shell.c</code>），外加在 <code>-O2 -flto=thin</code> 下为这两个 Linux 目标平台编译 SQLite，以及在 <code>-O0 -g</code> 与 <code>-O2</code> 下为 <code>x86_64-w64-mingw32</code> 编译 SQLite。</li><li><strong>预编译头与编辑器前导头（preamble）</strong>：一份共用的预编译头，在 <code>-O0 -g</code>、<code>-O2</code> 与 <code>-fsyntax-only</code> 下读取并对 <code>absl::</code> 执行代码补全；同时从每个 Abseil 源文件开头的 <code>#include</code> 块提取前导头，为每个文件单独预编译一次，再模拟编辑器的行为用它解析函数体并对 <code>std::</code> 和 <code>absl::</code> 执行代码补全。</li><li><strong>C++20 模块与 P1689 依赖扫描</strong>：在 <code>-std=c++23</code> 下编译 <code>libc++</code> 的 <code>std</code> 与 <code>std.compat</code>、<code>magic_enum</code>、<code>Vulkan-Hpp</code>（在 <code>x86_64</code> 上编译 <code>vulkan.cppm</code> 与 <code>vulkan_video.cppm</code>）、封装为模块的 <code>nlohmann/json</code>、包含多个分区的 <code>geometry</code> 模块（<code>shapes</code>、<code>detail</code>、<code>algorithms</code>），以及所有 import 它们的文件。在 <code>-O2</code> 下，模块分两步构建（先用 <code>--precompile</code> 生成 <code>.pcm</code>，再由 <code>.pcm</code> 编译为 <code>.o</code>）；在 <code>-O0 -g</code> 下，使用精简模块文件（<code>-fmodules-reduced-bmi -fmodule-output=</code>）单步完成构建。随后运行 <code>clang-scan-deps -format=p1689</code> 扫描单条编译命令（模拟 CMake 的调用方式）以及完整的 Abseil <code>compile_commands.json</code> 数据库。</li><li><strong>代码补全</strong>：在 Abseil 源文件、预编译头使用方、前导头以及 import 模块的文件上运行 <code>-fsyntax-only -Xclang -code-completion-at=...</code>（补全 <code>std::</code>、<code>nlohmann::</code>、<code>magic_enum::</code>、<code>geometry::</code>、<code>vk::</code>、<code>j.</code>）。</li><li><strong>链接</strong>：通过 <code>lld</code> 执行 ELF 链接（包括在 <code>-O0 -g</code>、<code>-O2</code> 与 <code>-O2 -flto=thin</code> 下链接 <code>x86_64</code> 和 <code>aarch64</code> Linux 程序，以及链接各模块示例程序）与 COFF 链接（在 <code>-O0 -g</code> 与 <code>-O2</code> 下链接 <code>x86_64-w64-mingw32</code> 的 SQLite）。</li></ul><p>整个训练过程在约 23 分钟内运行约 1,700 次调用，为每个版本合并生成一份 profile，并作为 <code>xclang-&lt;version&gt;.profdata</code> 发布（<a href="./../reference/releases#assets">版本发布</a>）。</p><p>目前的训练语料尚未涵盖 Objective-C、<code>clang-cl</code> 与 MSVC 模式解析、Mach-O 链接（<code>ld64.lld</code>）、<code>aarch64</code> COFF 链接、仅在 Windows 或 macOS 主机上执行的代码路径、sanitizer 编译趟（pass），以及 <code>clang</code> 自身不调用的 <code>libclang</code> 库（如 <code>clang-tidy</code> 检查项、<code>clangIndex</code>、<code>clangIncludeCleaner</code>）。扩充训练语料以覆盖这些路径已在<a href="./roadmap#pgo-training">计划中</a>，并在各版本之间持续推进。</p><h2 id="一份-profile-通用于所有主机" tabindex="-1">一份 Profile 通用于所有主机 <a class="header-anchor" href="#一份-profile-通用于所有主机" aria-label="Permalink to &quot;一份 Profile 通用于所有主机&quot;">​</a></h2><p><code>clang</code> 支持两种 PGO 插桩模式，决定了在一台主机上采集的 profile 能否用于优化另一台主机：</p><ul><li><strong>IR 插桩</strong>（<code>-fprofile-generate</code>）：在早期优化趟之后对 LLVM IR 插桩，并对此时每个函数的控制流图计算哈希。由于早期优化趟会参考目标平台的代价模型，同一个源码函数在 <code>x86_64</code> 与 <code>arm64</code> 上可能生成不同的控制流图，导致在一种架构上采集的 profile 无法匹配另一种架构。</li><li><strong>前端插桩</strong>（<code>-fprofile-instr-generate</code>，对应 LLVM 的 <code>LLVM_BUILD_INSTRUMENTED=Frontend</code>）：直接对 <code>clang</code> AST 插桩，并根据函数的源码结构计算哈希。同一份源码在所有目标平台上都会生成相同的哈希。</li></ul><p>xclang 采用前端插桩。在 23.1.2.1 之前的实验中，在 Linux x64 上采集的 profile 在全部六个主机平台上都能匹配 113,000 个函数中的几乎全部（每个平台仅差 0 或 1 个函数），且所得编译耗时与合并全部六个主机各自采集的 IR profile 相比，差异在 runner 波动误差范围内（下表为编译 Abseil / LLVM <code>Sema</code> 相对于不启用 PGO 的耗时比值，取五台 runner 的中位数）：</p><table tabindex="0"><thead><tr><th>主机</th><th>前端插桩（单份 Linux profile）</th><th>IR 插桩（六个主机的 profile 合并）</th></tr></thead><tbody><tr><td>Linux x64</td><td>0.725 / 0.727</td><td>0.722 / 0.721</td></tr><tr><td>Linux arm64</td><td>0.814 / 0.800</td><td>0.826 / 0.844</td></tr><tr><td>macOS arm64</td><td>0.905 / 0.818</td><td>0.895 / 0.864</td></tr><tr><td>Windows x64</td><td>0.771 / 0.792</td><td>0.764 / 0.820</td></tr></tbody></table><p>因此，训练只需在单台 Linux x64 runner 上运行一次，生成的 profile 即可用于优化全部六个主机的工具链与 <code>libclang</code> 压缩包，无需在各个主机上分别构建插桩版本或借助模拟器运行。</p><h3 id="重映射文件" tabindex="-1">重映射文件 <a class="header-anchor" href="#重映射文件" aria-label="Permalink to &quot;重映射文件&quot;">​</a></h3><p>前端 profile 按修饰名（mangled name）查找每个函数，而固定宽度整数类型与指针大小整数类型在 LP64 与 LLP64/Darwin ABI 下的名称修饰规则不同：<code>size_t</code> 与 <code>uint64_t</code> 在 Linux 上是 <code>unsigned long</code>（编码为 <code>m</code>），但在 Windows 上是 <code>unsigned long long</code>（编码为 <code>y</code>；在 macOS 上 <code>uint64_t</code> 也是 <code>unsigned long long</code>）；而 <code>int64_t</code> 在 Linux 上是 <code>long</code>（<code>l</code>），在 Windows 与 macOS 上则是 <code>long long</code>（<code>x</code>）。如果不做重映射，参数含有 <code>size_t</code> 或 <code>uint64_t</code> 的函数在 Windows 与 macOS 上的修饰名就会与 Linux profile 中的记录不同，从而无法获得 profile 计数。</p><p>为此，<a href="https://github.com/clice-io/xclang/blob/main/toolchain/pgo/remap.txt" target="_blank" rel="noreferrer"><code>toolchain/pgo/remap.txt</code></a> 通过 <code>-fprofile-remapping-file</code> 映射了 <code>type m y</code> 与 <code>type l x</code>。在同一批 23.1.2.1 之前的实验中，加入重映射文件后，Abseil / <code>Sema</code> 的相对编译耗时在 macOS arm64 上从 <code>0.896 / 0.923</code> 改善到了 <code>0.794 / 0.845</code>，在 Windows x64 上从 <code>0.787 / 0.824</code> 改善到了 <code>0.772 / 0.829</code>。</p><p>还有两小类函数无法通过 LLVM 的重映射器匹配：</p><ul><li>在 Windows 上，有 230 个带有上述类型整数字面量模板实参的函数（占总计数的 1.8%）。</li><li>具有内部链接的函数：在 Windows 上有 122 个，在 macOS 上有 39 个（分别占总计数的 0.06% 与 0.02%），因为前端 profile 中 <code>static</code> 函数的键格式为 <code>&lt;file&gt;:&lt;mangled&gt;</code>，而重映射器在解析修饰名前不会剥离 <code>&lt;file&gt;:</code> 前缀。</li></ul><h2 id="实测收益" tabindex="-1">实测收益 <a class="header-anchor" href="#实测收益" aria-label="Permalink to &quot;实测收益&quot;">​</a></h2><p><code>bench.yml</code>（<code>tests/bench/bench.ts</code>）使用未包含在训练语料中的代码，在各主机平台的 runner 上测量本机编译耗时：</p><ul><li><code>fmt</code> 的十个测试文件（重度使用模板的 C++20 代码）；</li><li><code>lua</code> 的 C 源文件；</li><li>预编译 <code>libc++</code> 的 <code>std</code> 模块。</li></ul><p>每项负载分别在 <code>-fsyntax-only</code>、<code>-O0 -g</code> 与 <code>-O2</code> 下逐文件单进程编译。测试在同一台 runner 上按轮次交替轮换各编译器的执行顺序，先取单机多轮测试的中位数，再取各机器相对于基准编译器比值的跨机中位数。百分之几以内的差异属于 runner 的正常波动。</p><p>基准编译器为同版本的 LLVM 官方发布构建：在 Linux 与 macOS 上启用了 PGO 与 ThinLTO（Linux x64 上还启用了 BOLT；为 xclang 的 Linux 主机启用 BOLT 目前在<a href="./roadmap#bolt">研究中</a>），在 Windows 上则启用了 PGO 但未启用 LTO。由于 LLVM 官方未发布 <code>x86_64</code> macOS 二进制包，在 <code>x86_64</code> macOS 上以 xclang 自身作为基准。</p><h3 id="_23-1-2-6" tabindex="-1">23.1.2.6 <a class="header-anchor" href="#_23-1-2-6" aria-label="Permalink to &quot;23.1.2.6&quot;">​</a></h3><p>相对于 LLVM 23.1.2 官方发布构建的编译耗时比值，每个主机取五台 runner 的中位数，测于 2026-10-06（<a href="https://github.com/clice-io/xclang/actions/runs/37356476645" target="_blank" rel="noreferrer">运行记录 37356476645</a>，测量已发布的 23.1.2.6 压缩包；Linux x64 因其中一个任务在基准测试前统计体积时失败而取四台 runner）。标有 <code>llvm.exe</code> 的行直接调用 <code>llvm.exe clang++</code>，不经过 <code>clang++.exe</code> 启动器：</p><table tabindex="0"><thead><tr><th>主机</th><th>fmt（语法检查 / O0 / O2）</th><th>lua（语法检查 / O0 / O2）</th><th>std（O0 / O2）</th></tr></thead><tbody><tr><td>Linux x64</td><td>1.035 / 1.009 / 1.069</td><td>1.118 / 1.062 / 1.109</td><td>1.013 / 1.022</td></tr><tr><td>Linux arm64</td><td>1.000 / 0.976 / 1.042</td><td>1.082 / 1.011 / 1.075</td><td>0.970 / 0.994</td></tr><tr><td>macOS arm64</td><td>0.902 / 0.935 / 1.014</td><td>1.169 / 0.971 / 0.959</td><td>0.980 / 0.890</td></tr><tr><td>Windows x64</td><td>0.798 / 0.825 / 0.890</td><td>1.083 / 1.050 / 1.001</td><td>0.777 / 0.849</td></tr><tr><td>Windows x64, <code>llvm.exe</code></td><td>0.798 / 0.809 / 0.885</td><td>0.968 / 0.960 / 0.974</td><td>0.821 / 0.844</td></tr><tr><td>Windows arm64</td><td>0.888 / 0.906 / 0.954</td><td>1.271 / 1.212 / 1.167</td><td>0.925 / 0.940</td></tr><tr><td>Windows arm64, <code>llvm.exe</code></td><td>0.860 / 0.898 / 0.947</td><td>1.019 / 1.065 / 1.056</td><td>0.915 / 0.932</td></tr></tbody></table><p>同一批 macOS runner 上也运行了 Apple 的 <code>clang</code>：在 <code>arm64</code> 上（相对于 LLVM 官方构建），它在 <code>fmt</code> 上的耗时比值为 <code>1.097 / 1.207 / 1.206</code>，在 <code>lua</code> 上为 <code>0.879 / 0.875 / 1.004</code>；在 <code>x86_64</code> 上（相对于 xclang），它在 <code>fmt</code> 上为 <code>1.168 / 1.223 / 1.221</code>，在 <code>lua</code> 上为 <code>0.841 / 0.973 / 0.990</code>。</p><p>23.1.2.6 实测结果小结：</p><ul><li><strong>Linux 与 macOS</strong>：在 C++ 代码上，xclang 与 LLVM 官方的 PGO+ThinLTO 构建表现持平；在 <code>lua</code> 的小型 C 文件上耗时最多增加 17%。在 LLVM 官方二进制文件额外经过 BOLT 优化的 Linux x64 上，xclang 在 C++ 上耗时最多增加 7%，在 C 上最多增加 12%。</li><li><strong>Windows</strong>：相比 LLVM 使用 MSVC 构建的 <code>clang</code>（启用 PGO 但未启用 LTO），xclang 使用 MinGW 构建的 <code>clang</code>（启用 PGO 与 ThinLTO）在 C++ 编译上耗时在 x64 上缩短 11% 至 22%，在 arm64 上缩短 5% 至 11%。</li><li><strong>Windows 启动器开销</strong>：<code>lua</code> 的每个 C 文件只需几十毫秒即可编译完成，因此相比直接运行 <code>llvm.exe clang++</code>，先启动 <code>clang++.exe</code> 再拉起 <code>llvm.exe</code> 在 x64 上最多增加 12% 耗时，在 arm64 上最多增加 25% 耗时；而在 C++ 文件上，进程启动开销可以忽略不计（<a href="./windows#the-launchers">启动器</a>）。</li><li><strong>Apple 的 <code>clang</code></strong>：在两种 macOS 架构上编译 <code>fmt</code> 均比 xclang 多花 17% 至 29% 的时间，而在 <code>lua</code> 上的耗时则介于快 25% 到慢 5% 之间。</li></ul><h3 id="_23-1-2-1" tabindex="-1">23.1.2.1 <a class="header-anchor" href="#_23-1-2-1" aria-label="Permalink to &quot;23.1.2.1&quot;">​</a></h3><p>相对于 LLVM 23.1.2 官方发布构建的编译耗时比值，取三台 runner 的中位数（Linux 与 macOS 见<a href="https://github.com/clice-io/xclang/actions/runs/36249036595" target="_blank" rel="noreferrer">运行记录 36249036595</a>，Windows 见<a href="https://github.com/clice-io/xclang/actions/runs/36250216010" target="_blank" rel="noreferrer">运行记录 36250216010</a>），最后一列为不启用 PGO profile 编译的同一 xclang 构建（<code>no PGO, fmt</code>）：</p><table tabindex="0"><thead><tr><th>主机</th><th>fmt（语法检查 / O0 / O2）</th><th>lua</th><th>std（O0 / O2）</th><th>未启用 PGO，fmt</th></tr></thead><tbody><tr><td>Linux x64</td><td>1.031 / 1.006 / 1.046</td><td>1.106 / 1.061 / 1.098</td><td>1.047 / 1.022</td><td>1.279 / 1.250 / 1.244</td></tr><tr><td>Linux arm64</td><td>0.972 / 0.957 / 1.018</td><td>1.012 / 0.968 / 1.050</td><td>0.959 / 0.964</td><td>1.283 / 1.237 / 1.272</td></tr><tr><td>macOS arm64</td><td>0.986 / 0.983 / 1.050</td><td>0.948 / 0.804 / 0.994</td><td>0.860 / 0.955</td><td>1.367 / 1.323 / 1.353</td></tr><tr><td>Windows x64</td><td>0.809 / 0.830 / 0.893</td><td>1.075 / 1.049 / 1.041 (<code>llvm.exe</code>: 1.044 / 0.987 / 1.020)</td><td>0.885 / 1.021</td><td>1.226 / 1.155 / 1.227</td></tr><tr><td>Windows arm64</td><td>0.899 / 0.916 / 0.958</td><td>1.332 / 1.238 / 1.187 (<code>llvm.exe</code>: 1.090 / 1.058 / 1.079)</td><td>0.944 / 0.939</td><td>1.178 / 1.150 / 1.162</td></tr></tbody></table><ul><li><strong>Profile 的效果</strong>：不启用 PGO 时，同一份 ThinLTO 构建在 <code>fmt</code> 上的耗时是 LLVM 官方发布构建的 1.15 至 1.37 倍；启用 Linux 前端 profile 后，编译耗时降低了 16% 至 34%。</li><li><strong><code>x86_64</code> macOS runner 的波动误差</strong>：在六类 runner 中波动最大的 <code>macos-15-intel</code> 上，23.1.2.1 未启用 PGO 的构建相对于启用 PGO 的 xclang 测得比值在 <code>0.84</code> 至 <code>1.12</code> 之间，Apple 的 <code>clang</code> 在 <code>fmt</code> 上测得 <code>0.89</code> 至 <code>1.08</code>（在 <code>lua</code> 上为 <code>0.57</code> 至 <code>0.87</code>），而在 23.1.2.6 的五台 runner 测试中，Apple 的 <code>clang</code> 在 <code>fmt</code> 上则慢了 17% 至 22%。因此，在波动误差范围之外，尚不能确定 PGO 是否对交叉编译出的 <code>x86_64</code> macOS 主机程序在 Intel Mac 上的运行有明显提升。</li></ul>',33)])])}const m=d(n,[["render",a]]);export{h as __pageData,m as default};
